android.extraProguardRules:
# R8 strips anything it cannot see being called, and everything below is
# reached by reflection or from native code, so it looks unused to R8.

# Sentry resolves integrations by name and needs readable line numbers for
# the stack traces to be worth anything.
-keep class io.sentry.** { *; }
-keepattributes LineNumberTable,SourceFile

# RevenueCat and Google Mobile Ads both build objects from JSON at runtime.
-keep class com.revenuecat.purchases.** { *; }
-keep class com.google.android.gms.ads.** { *; }

# React Native bridge surface: native modules and their exported methods are
# looked up by name from JavaScript, never called from Java.
-keep,allowobfuscation @interface com.facebook.proguard.annotations.DoNotStrip
-keep @com.facebook.proguard.annotations.DoNotStrip class * { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod *; }
-keep class com.facebook.jni.** { *; }

# Class repackaging: R8 moves classes into one package so the DEX file is
# smaller and loads faster. Play reports it as missing, and AGP 9.1 will do it
# by default. The keep rules above already protect everything that is looked up
# by name.
-repackageclasses ''
